 researchFeature(r,{researchFeatureId:'RF_CONFIRM_SCREEN',name:'ボーナス確定画面振り分け',factStatus:'verified',candidateModel:'multinomial',trialUnit:'ボーナス確定画面1回',observationScope:'ボーナス確定画面',numeratorDefinition:'各確定画面キャラの出現回数',denominatorDefinition:'確認したボーナス確定画面回数',categories:['EVEN_A','EVEN_B','EVEN_C','EVEN_D','ODD_A','ODD_B','YOU','MORA'],settingDistributions:{SET_1:{EVEN_A:.11,EVEN_B:.11,EVEN_C:.11,EVEN_D:.11,ODD_A:.27,ODD_B:.27,YOU:.02,MORA:0},SET_2:{EVEN_A:.134,EVEN_B:.134,EVEN_C:.134,EVEN_D:.134,ODD_A:.22,ODD_B:.22,YOU:.024,MORA:0},SET_3:{EVEN_A:.109,EVEN_B:.109,EVEN_C:.109,EVEN_D:.109,ODD_A:.267,ODD_B:.267,YOU:.028,MORA:0},SET_4:{EVEN_A:.132,EVEN_B:.132,EVEN_C:.132,EVEN_D:.132,ODD_A:.217,ODD_B:.217,YOU:.032,MORA:.005},SET_5:{EVEN_A:.108,EVEN_B:.108,EVEN_C:.108,EVEN_D:.108,ODD_A:.263,ODD_B:.263,YOU:.036,MORA:.006},SET_6:{EVEN_A:.131,EVEN_B:.131,EVEN_C:.131,EVEN_D:.131,ODD_A:.214,ODD_B:.214,YOU:.04,MORA:.007}},distributionMode:'explicit_complete',sourceRefs:['SRC_SLOPACHI_CONFIRM'],crossSourceStatus:'matched',notes:'MORAは設定4以上Evidenceとして分離し、残り画面を条件付きMultinomialに利用可能。'});
 const confirmCats=['EVEN_A','EVEN_B','EVEN_C','EVEN_D','ODD_A','ODD_B','YOU'];const confirmIds=addMultiInputs(s,u,'ボーナス確定画面（割合）','INP_CONFIRM',confirmCats,{EVEN_A:'メイメイ',EVEN_B:'♡あゃ♡',EVEN_C:'Elly',EVEN_D:'碧',ODD_A:'Dr.D',ODD_B:'アルバーノ',YOU:'YOU'});setMultinomial(s,{researchFeatureId:'RF_CONFIRM_SCREEN',featureId:'FEAT_CONFIRM_SCREEN_NON_EVIDENCE',ids:confirmIds,exclude:['MORA'],reason:'モラ・ガラテア&ひろし&BJは設定4以上Evidenceとして分離し、それ以外の奇偶・高設定示唆画面を条件付き分布として利用します。',sample:20});uiSection(u,'ボーナス確定画面（割合）',{description:'設定確定画面はEvidenceへ入力し、それ以外の確定画面キャラの出現回数を割合用に入力します。'});
