 const base='research/L_INUYASHA2_FK';const r=read(`${base}/research-data.json`),s=read(`${base}/selection-data.json`),u=read(`${base}/ui-design-data.json`),o=read(`${base}/machine-observation-data.json`);bump(r,s);
